import{_ as t,o as i,c as o,al as a}from"./chunks/framework.7vp1BMOE.js";const _=JSON.parse('{"title":"VTOL Ice Shedding feature","description":"","frontmatter":{},"headers":[],"relativePath":"en/config_vtol/vtol_ice_shedding.md","filePath":"en/config_vtol/vtol_ice_shedding.md"}'),r={name:"en/config_vtol/vtol_ice_shedding.md"};function s(n,e,d,c,l,h){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="vtol-ice-shedding-feature" tabindex="-1">VTOL Ice Shedding feature <a class="header-anchor" href="#vtol-ice-shedding-feature" aria-label="Permalink to &quot;VTOL Ice Shedding feature&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Ice shedding is a feature that periodically spins unused motors in fixed-wing flight, to break off any ice that is starting to build up in the motors while it is still feasible to do so.</p><p>It is configured by the parameter <code>CA_ICE_PERIOD</code>. When it is 0, the feature is disabled, when it is above 0, it sets the duration of the ice shedding cycle in seconds. In each cycle, the rotors are spun for two seconds at a motor output of 0.01.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>When enabling the feature on a new airframe, there is the risk of producing torques that disturb the fixed-wing rate controller. To mitigate this risk:</p><ul><li>Set your <code>PWM_MIN</code> values correctly, so that the motor output 0.01 actually produces 1% thrust</li><li>Be prepared to take control and switch back to multicopter</li></ul></div>',5)])])}const f=t(r,[["render",s]]);export{_ as __pageData,f as default};
